import{_ as t,o,c as d,a2 as a}from"./chunks/framework.Ch4PdLd_.js";const h=JSON.parse('{"title":"Durable 会话与崩溃续跑","description":"","frontmatter":{},"headers":[],"relativePath":"reference/durable-sessions.md","filePath":"reference/durable-sessions.md"}'),c={name:"reference/durable-sessions.md"};function s(r,e,n,l,i,p){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="durable-会话与崩溃续跑" tabindex="-1">Durable 会话与崩溃续跑 <a class="header-anchor" href="#durable-会话与崩溃续跑" aria-label="Permalink to &quot;Durable 会话与崩溃续跑&quot;">​</a></h1><p>nek 的每一轮都运行在 durable 引擎（<code>@earendil-works/pi-durable</code>）上。一轮里的每一步都会先提交到会话数据库，再开始下一步：用户输入、流式文本、每个工具调用和结果、排队的消息、压缩。进程意外终止（崩溃、<code>kill</code>、关闭终端、断电）后重新打开会话，中断的那一轮会继续，而不是丢失。</p><h2 id="续跑中断的一轮" tabindex="-1">续跑中断的一轮 <a class="header-anchor" href="#续跑中断的一轮" aria-label="Permalink to &quot;续跑中断的一轮&quot;">​</a></h2><p>像平常一样重新打开会话，例如 <code>nek -c</code> 或 <code>/resume</code>，中断的工作会自动继续：</p><table tabindex="0"><thead><tr><th>中断时正在</th><th>重新打开后</th></tr></thead><tbody><tr><td>模型流式输出</td><td>已输出的部分作为“已中止”的回复保留在历史里，请求重新发送</td></tr><tr><td>只读工具（<code>read</code>、<code>grep</code>、<code>find</code>、<code>ls</code>、<code>ast_grep</code>、<code>web_search</code>）</td><td>工具重新执行</td></tr><tr><td>其他工具（<code>bash</code>、<code>edit</code>、<code>write</code>、MCP 和扩展工具）</td><td>调用结果保留已有的部分输出并注明“已中断”，这一轮继续；由模型决定是否重新执行。<strong>不会</strong>自动重跑，因为副作用可能已经发生</td></tr><tr><td>nek 的协作工具（<code>ask_question</code>、<code>switch_mode</code>、<code>todo_write</code>、<code>await</code>、<code>subagent</code>）</td><td>重新执行</td></tr><tr><td>前台子代理</td><td>重新打开<strong>同一个</strong>子会话，让它继续自己中断的那一轮，结果照常返回父会话</td></tr><tr><td>提问框或模式切换确认框</td><td>重新弹出</td></tr><tr><td>排队的插话或追加消息</td><td>仍在队列中，按顺序送达</td></tr><tr><td><code>/compact</code></td><td>压缩重新执行</td></tr><tr><td>扩展的 <code>agent_before_settle</code> 处理</td><td>重新执行</td></tr></tbody></table><p>中断的工作在扩展收到 <code>session_start</code> 之后才恢复，保证重跑工具之前扩展的状态已经恢复。</p><p>扩展工具用 <code>replay: &quot;safe&quot;</code> 声明自己可以安全地执行两次；这样的工具可以用 <code>ctx.getToolCallMemo(toolCallId)</code> 在两次执行之间保存值（<code>set()</code> 保存的值在崩溃后同一调用重跑时由 <code>get()</code> 返回）。<code>subagent</code> 工具就是用它找回自己启动的子会话。见 <a href="/nekcode/develop/extensions#tools">编写扩展</a>。</p><p>后台子代理在父会话重开后不会自动接回，在 <code>resume</code> 或 <code>await</code> 它时才处理。</p><h2 id="存储" tabindex="-1">存储 <a class="header-anchor" href="#存储" aria-label="Permalink to &quot;存储&quot;">​</a></h2><p>每个会话是一个 SQLite 数据库：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;时间戳&gt;_&lt;会话ID&gt;.sqlite      会话数据库</span></span>
<span class="line"><span>&lt;时间戳&gt;_&lt;会话ID&gt;.meta.json   /resume 列表的缓存，缺失或过期时从数据库重建</span></span>
<span class="line"><span>&lt;时间戳&gt;_&lt;会话ID&gt;.lock        打开会话的进程持有的锁</span></span></code></pre></div><p>同一个会话不能被两个进程同时打开。</p><p>打开旧的 <code>.jsonl</code> 会话时，nek 把它导入同名的 <code>.sqlite</code>，<code>.jsonl</code> 文件保持不变。见 <a href="/nekcode/reference/session-format">会话文件格式</a>。</p><h2 id="与旧的代理循环的差异" tabindex="-1">与旧的代理循环的差异 <a class="header-anchor" href="#与旧的代理循环的差异" aria-label="Permalink to &quot;与旧的代理循环的差异&quot;">​</a></h2><p>会话 API、事件和扩展钩子没有变化，个别行为有所不同：</p><ul><li><strong>重试</strong>：一次运行包含它的自动重试，监听器只在最后收到一个 <code>agent_end</code>（<code>willRetry: false</code>）。每次失败的尝试仍会结束自己的一轮（带错误的 <code>turn_end</code>），<code>auto_retry_start</code> / <code>auto_retry_end</code> 照常发出；</li><li><strong>流式粒度</strong>：流式文本大约每秒提交十次，所以 <code>message_update</code> 事件的步子更大；</li><li><strong>并行工具</strong>：并行调用的 <code>tool_execution_end</code> 按完成顺序到达；</li><li><strong>请求前中止</strong>：在运行准备第一次请求时中止，不会发出请求，历史里仍会有一个空的已中止回复；</li><li><strong>系统提示词和工具变化</strong>作为按位置排列的系统条目保存在历史里，请求看到的提示词和工具与之前相同；</li><li><strong><code>session.agent</code></strong> 为兼容而保留会话状态（<code>state</code>、<code>transport</code>），它自己的循环不再运行，<code>agent.subscribe()</code> 的监听器会收到这一轮的循环事件并按事件逐个等待；</li><li><strong>分支</strong>以同一数据库中的分叉对话保存，<code>/tree</code>、<code>/fork</code> 和分支摘要照常工作。</li></ul><h2 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><ul><li>正常退出后，会话目录里可能残留 <code>.sqlite-wal</code> / <code>.sqlite-shm</code> 文件，不影响正确性。</li><li>上游服务卡住但没有断开连接时，nek 无法区分“模型还在思考”和“流已经死了”，要等 <code>httpIdleTimeoutMs</code>（默认 5 分钟）才会报错并重试。</li></ul>`,18)])])}const g=t(c,[["render",s]]);export{h as __pageData,g as default};
